//! RDKit parity on the diverse benchmark set (`benches/data/set/`,
//! generated by `tools/gen_bench_set.py`): energy at the initial structure,
//! energy at RDKit's optimized structure, and our minimization from the
//! initial structure vs RDKit's optimized structure — for MMFF94 and UFF,
//! with the reference path and the fast (exact) path.

use molecule_optimizer_rs::Molecule;
use molecule_optimizer_rs::core::geometry::kabsch_rmsd;
use molecule_optimizer_rs::fast::{FastBuilder, FastOptions};
use molecule_optimizer_rs::ff::mmff::MmffBuilder;
use molecule_optimizer_rs::ff::uff::UffBuilder;
use molecule_optimizer_rs::ff::{ForceField, ForceFieldBuilder};
use molecule_optimizer_rs::io::molfile::read_sdf_lenient;
use molecule_optimizer_rs::optim::{MinimizeOptions, MinimizeStatus, NoObserver, minimize};
use std::collections::HashMap;
use std::path::PathBuf;

fn set_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("benches/data/set")
}

fn load(file: &str) -> Vec<Molecule> {
    let text = std::fs::read_to_string(set_dir().join(file)).unwrap();
    read_sdf_lenient(&text).into_iter().map(|r| r.expect("parse")).collect()
}

fn prop(m: &Molecule, k: &str) -> f64 {
    m.props[k].trim().parse().unwrap()
}

fn rmsd_heavy(m: &Molecule, a: &[[f64; 3]], b: &[[f64; 3]]) -> f64 {
    let h = m.heavy_atoms();
    let pa: Vec<_> = h.iter().map(|&i| a[i]).collect();
    let pb: Vec<_> = h.iter().map(|&i| b[i]).collect();
    kabsch_rmsd(&pa, &pb)
}

/// Molecules whose result depends on ring order (our ring perception orders
/// rings differently from RDKit; being fixed by porting RDKit's ring finding).
const KNOWN_DIFFERENCES: &[(&str, &str)] = &[("MMFF", "fullerene_C60")];

fn check(kind: &str, builder: &dyn ForceFieldBuilder, label: &str) {
    let initial: HashMap<String, Molecule> = load("initial.sdf").into_iter().map(|m| (m.name.clone(), m)).collect();
    let opt = load(&format!("{}_opt.sdf", kind.to_lowercase()));
    let mut worst_e0 = 0.0f64;
    let mut worst_eopt = 0.0f64;
    let mut worst_min_e = 0.0f64;
    let mut worst_rmsd = 0.0f64;
    let mut failures = Vec::new();
    for o in &opt {
        if KNOWN_DIFFERENCES.contains(&(kind, o.name.as_str())) {
            println!("{label}: skipping known difference {}", o.name);
            continue;
        }
        let m0 = &initial[&o.name];
        let e0_ref = prop(o, "E_INITIAL");
        let eopt_ref = prop(o, "E_OPT");
        let ff = builder.build_dyn(m0, &[]).unwrap_or_else(|e| panic!("{}: {e}", o.name));
        let mut pos = m0.flat_coords();
        let e0 = ff.energy(&pos);
        let e_at_opt = ff.energy(&o.flat_coords());
        let scale = |e: f64| e.abs().max(1.0);
        if (e0 - e0_ref).abs() / scale(e0_ref) > 1e-9 {
            println!("MISMATCH {label} {}: ours {e0:.6} rdkit {e0_ref:.6}", o.name);
        }
        worst_e0 = worst_e0.max((e0 - e0_ref).abs() / scale(e0_ref));
        worst_eopt = worst_eopt.max((e_at_opt - eopt_ref).abs() / scale(eopt_ref));
        let opts = MinimizeOptions { max_iters: prop(o, "OPT_MAX_ITERS") as usize, ..Default::default() };
        let r = minimize(&ff, &mut pos, &opts, &mut NoObserver);
        let ours: Vec<[f64; 3]> = pos.chunks(3).map(|c| [c[0], c[1], c[2]]).collect();
        let de = (r.energy - prop(o, "E_MIN")).abs();
        let rmsd = rmsd_heavy(m0, &ours, &o.coords);
        worst_min_e = worst_min_e.max(de);
        worst_rmsd = worst_rmsd.max(rmsd);
        let rdkit_converged = prop(o, "OPT_RESULT") == 0.0;
        let ours_converged = r.status == MinimizeStatus::Converged;
        if de > 1e-4 || rmsd > 1e-3 || rdkit_converged != ours_converged {
            failures.push(format!("{}: dE={de:.3e} rmsd={rmsd:.3e} conv rdkit={rdkit_converged} ours={ours_converged}", o.name));
        }
    }
    println!(
        "{label}: {} molecules; max rel dE(initial)={worst_e0:.2e}, max rel dE(at RDKit opt)={worst_eopt:.2e}, \
         minimization: max |dE|={worst_min_e:.2e} kcal/mol, max heavy RMSD={worst_rmsd:.2e} A",
        opt.len()
    );
    assert!(worst_e0 < 1e-9, "{label}: initial energy mismatch {worst_e0}");
    assert!(worst_eopt < 1e-9, "{label}: energy at RDKit-optimized structure mismatch {worst_eopt}");
    assert!(failures.is_empty(), "{label}: minimization differs from RDKit:\n{}", failures.join("\n"));
}

#[test]
fn mmff_reference_path() {
    check("MMFF", &MmffBuilder::default(), "MMFF94");
}

#[test]
fn uff_reference_path() {
    check("UFF", &UffBuilder::default(), "UFF");
}

#[test]
fn mmff_fast_exact_path() {
    check("MMFF", &FastBuilder::new(MmffBuilder::default(), FastOptions::exact()), "MMFF94/fast");
}

#[test]
fn uff_fast_exact_path() {
    check("UFF", &FastBuilder::new(UffBuilder::default(), FastOptions::exact()), "UFF/fast");
}
